INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass breitere Aufgaben immer die Motivation steigern. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Person und Aufgabe ab"}, {"text": "Ja", "correct": false, "because": "Nicht universell zutreffend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einem Kollegen mehr IT-Aufgaben zuweise?', 3, '[{"text": "Schulung", "correct": true, "because": "Sichert Kompetenz"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität ist wichtiger"}, {"text": "Hardware", "correct": false, "because": "Nicht primär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern eine erfolgreiche Aufgabenvielfalt?', 5, '[{"text": "Klare Kommunikation", "correct": true, "because": "Verhindert Missverständnisse"}, {"text": "Schulungsangebote", "correct": true, "because": "Baut Wissen auf"}, {"text": "Höhere Gehälter", "correct": false, "because": "Motiviert, aber nicht zentral"}, {"text": "Weniger Kontrolle", "correct": false, "because": "Kann Chaos verursachen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mehr Aufgaben erhöhen die Verantwortung. b) Sie führen immer zu Überlastung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überlastung ist nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einem Team mehr IT-Verantwortung gebe?', 4, '[{"text": "Kompetenz", "correct": false, "because": "Muss geprüft werden"}, {"text": "Zeitmanagement", "correct": false, "because": "Schlüssel für Erfolg"}, {"text": "Büroausstattung", "correct": true, "because": "Sekundär für Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob neue Aufgaben immer Schulungen erfordern?', 2, '[{"text": "Nein", "correct": true, "because": "Vorwissen kann ausreichen"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich einem Kollegen Netzwerkaufgaben zuweise?', 3, '[{"text": "Wissensaufbau", "correct": true, "because": "Fördert Vielseitigkeit"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Nicht primär"}, {"text": "Weniger Teamarbeit", "correct": false, "because": "Kein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen breitere IT-Aufgaben effektiv?', 5, '[{"text": "Passende Qualifikation", "correct": true, "because": "Sichert Erfolg"}, {"text": "Klar definierte Ziele", "correct": true, "because": "Gibt Orientierung"}, {"text": "Höhere Bandbreite", "correct": false, "because": "Technisch irrelevant"}, {"text": "Weniger Meetings", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Mehr Aufgaben fördern Flexibilität. b) Sie reduzieren Spezialisierung. Stimmt das?', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Flexibilität steigt, Spezialisierung kann sinken"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist oft zutreffend"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einem Kollegen Backup-Aufgaben zu geben?', 4, '[{"text": "Technisches Wissen", "correct": false, "because": "Notwendig für Umsetzung"}, {"text": "Planung", "correct": false, "because": "Wichtig für Ablauf"}, {"text": "Firmenwagen", "correct": true, "because": "Irrelevant für Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind mehr Aufgaben immer besser fürs Team?', 2, '[{"text": "Nein", "correct": true, "because": "Balance ist entscheidend"}, {"text": "Ja", "correct": false, "because": "Überlastung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt es, einem Kollegen Sicherheitsaufgaben zuzuweisen?', 4, '[{"text": "Breiteres Wissen", "correct": true, "because": "Fördert Vielseitigkeit"}, {"text": "Verantwortung", "correct": true, "because": "Stärkt Eigenständigkeit"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass neue Aufgaben immer mehr Zeit kosten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Effizienz kann steigen"}, {"text": "Ja", "correct": false, "because": "Hängt von Organisation ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist entscheidend, wenn ich einem Team mehr Software-Aufgaben gebe?', 3, '[{"text": "Ressourcenplanung", "correct": true, "because": "Sichert Machbarkeit"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Qualität zählt"}, {"text": "Bunte Software", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Neue Aufgaben fördern Teamarbeit. b) Sie erhöhen immer den Stress.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Stress ist nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich, wenn ich Hardware-Aufgaben zuweise?', 5, '[{"text": "Technische Kenntnisse", "correct": true, "because": "Notwendig für Umsetzung"}, {"text": "Zeitplanung", "correct": true, "because": "Verhindert Engpässe"}, {"text": "Marketingziele", "correct": false, "because": "Nicht relevant"}, {"text": "Schnelle Ergebnisse", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich einem Kollegen mehr Netzwerkaufgaben gebe?', 3, '[{"text": "Schulung", "correct": false, "because": "Wissen ist nötig"}, {"text": "Zielvorgaben", "correct": false, "because": "Gibt Orientierung"}, {"text": "Kaffeemaschine", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördern neue Aufgaben immer die Kreativität?', 3, '[{"text": "Nein", "correct": true, "because": "Hängt von Aufgabe ab"}, {"text": "Ja", "correct": false, "because": "Nicht immer der Fall"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob mehr Aufgaben immer mehr Fehler verursachen?', 2, '[{"text": "Nein", "correct": true, "because": "Kompetenz kann Fehler reduzieren"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um einem Team mehr IT-Verantwortung zu geben?', 4, '[{"text": "Unterstützung", "correct": true, "because": "Sichert Erfolg"}, {"text": "Weniger Kontrolle", "correct": false, "because": "Kann Risiken erhöhen"}, {"text": "Schnelle Hardware", "correct": false, "because": "Nicht primär"}]');
